package domain

// ContentTextNone marks metadata that must not be projected as author text.
const ContentTextNone = "none"

// MessageContent describes observable content. Summary is generated by the
// service and must never be presented as the author's words. Metadata-only does
// not promise downloadable bytes. URLs and native parameter bags are excluded.
type MessageContent struct {
	TextRole     string           `json:"text_role"`
	Kind         string           `json:"kind"`
	NativeType   *string          `json:"native_type"`
	Summary      string           `json:"summary"`
	Availability string           `json:"availability"`
	Reason       *string          `json:"reason"`
	Elements     []ContentElement `json:"elements"`
}

type ContentElement struct {
	Kind           string  `json:"kind"`
	Label          *string `json:"label"`
	MIMEType       *string `json:"mime_type"`
	FileName       *string `json:"file_name"`
	SizeBytes      *int64  `json:"size_bytes"`
	DurationMS     *int64  `json:"duration_ms"`
	Width          *int64  `json:"width"`
	Height         *int64  `json:"height"`
	StickerID      *string `json:"sticker_id"`
	BytesAvailable bool    `json:"bytes_available"`
}

// LegacyContent states explicitly that the original native union was not
// retained. It must not infer photo/call/sticker from a missing text projection.
func LegacyContent() *MessageContent {
	reason := "legacy_projection"
	return &MessageContent{
		TextRole: "legacy_projection", Kind: "unsupported", NativeType: nil,
		Summary:      "Legacy content; original type unavailable",
		Availability: "unavailable", Reason: &reason, Elements: []ContentElement{},
	}
}

// SemanticText excludes attachment titles from typed message text while the
// legacy group/v2 projection remains byte-compatible for retained deliveries.
func (m Message) SemanticText() string {
	if m.Content != nil && m.Content.TextRole == "none" {
		return ""
	}
	return m.Text
}
